/*
 * Testeria — content/selector.js
 *
 * Generator selector multi-kandidat. Urutan prioritas (sesuai rencana):
 *   1. data-testid / data-test / data-cy / id (id ditolak bila terlihat auto-generated)
 *   2. name, aria-label, placeholder, role + accessible text
 *   3. CSS path pendek dengan nth-of-type (jalan terakhir) + XPath absolut
 *
 * Beberapa kandidat disimpan sekaligus; replayer mencobanya berurutan.
 * Semua kandidat adalah STRING murni (css / xpath / text) — tidak pernah dieval.
 *
 * Aman dievaluasi ulang (executeScript recovery): pola namespace globalThis.
 */
var selectorGen = (globalThis.TESTERIA_SELECTOR = globalThis.TESTERIA_SELECTOR || {});
(function () {
  "use strict";

  var MAX_TEXT_LEN = 80;
  var MAX_ANCESTORS = 5;
  var MAX_CANDIDATES = 6;

  // ---------------------------------------------------------------------------
  // Heuristik id auto-generated
  // ---------------------------------------------------------------------------
  function looksAutoGenerated(id) {
    if (!id) return true;
    if (id.length < 2) return true;
    if (/\d{4,}/.test(id)) return true; // 4+ digit berurutan
    if (/^[0-9a-f]{8,}$/i.test(id)) return true; // hex blob / uuid
    if (/^:r[0-9a-f]+:?$/i.test(id)) return true; // React useId ":r1:"
    if (/^(?:ember|react|ng|mui|chakra|radix|radium|css|sc|js_|__)[-_]?\d/i.test(id)) {
      return true; // prefix framework + digit
    }
    return false;
  }

  function cssEscape(s) {
    try {
      if (globalThis.CSS && globalThis.CSS.escape) return globalThis.CSS.escape(s);
    } catch (e) {}
    return String(s).replace(/([^a-zA-Z0-9_\u00A0-\uFFFF-])/g, "\\$1");
  }

  function attrValueEscape(v) {
    return String(v).replace(/\\/g, "\\\\").replace(/"/g, '\\"');
  }

  // ---------------------------------------------------------------------------
  // Text helpers
  // ---------------------------------------------------------------------------
  function directText(el) {
    var t = "";
    var nodes = el.childNodes || [];
    for (var i = 0; i < nodes.length; i++) {
      if (nodes[i].nodeType === 3) t += nodes[i].nodeValue || "";
    }
    return t.replace(/\s+/g, " ").trim();
  }

  /** Teks "accessible" untuk filter kandidat saat replay. */
  function accessibleText(el) {
    var t =
      el.getAttribute("aria-label") ||
      el.getAttribute("alt") ||
      (el.tagName === "INPUT" && (el.placeholder || el.value)) ||
      (el.tagName === "TEXTAREA" && el.placeholder) ||
      directText(el) ||
      // Fallback teks bersarang: label button/anchor sering dibungkus span/div
      // (mis. menu accordion) sehingga directText kosong — pakai textContent.
      (el.textContent || "").replace(/\s+/g, " ").trim() ||
      el.title ||
      "";
    t = String(t).replace(/\s+/g, " ").trim();
    return t.slice(0, MAX_TEXT_LEN);
  }

  selectorGen.elementMatchesText = function (el, text) {
    if (!text) return true;
    if (!el) return false;
    var candidates = [
      accessibleText(el),
      (el.textContent || "").replace(/\s+/g, " ").trim().slice(0, MAX_TEXT_LEN),
      el.value || ""
    ];
    var needle = String(text).toLowerCase();
    for (var i = 0; i < candidates.length; i++) {
      if (candidates[i] && candidates[i].toLowerCase() === needle) return true;
    }
    return false;
  };

  // ---------------------------------------------------------------------------
  // Role implisit (subset yang umum, cukup untuk v1)
  // ---------------------------------------------------------------------------
  var IMPLICIT_ROLES = {
    A: function (el) { return el.hasAttribute("href") ? "link" : null; },
    BUTTON: function () { return "button"; },
    H1: function () { return "heading"; },
    H2: function () { return "heading"; },
    H3: function () { return "heading"; },
    H4: function () { return "heading"; },
    H5: function () { return "heading"; },
    H6: function () { return "heading"; },
    IMG: function (el) { return el.hasAttribute("alt") ? "img" : null; },
    INPUT: function (el) {
      var t = (el.getAttribute("type") || "text").toLowerCase();
      if (t === "checkbox") return "checkbox";
      if (t === "radio") return "radio";
      if (t === "button" || t === "submit" || t === "reset") return "button";
      if (t === "search") return "searchbox";
      return "textbox";
    },
    TEXTAREA: function () { return "textbox"; },
    SELECT: function (el) { return el.hasAttribute("multiple") ? "listbox" : "combobox"; },
    OPTION: function () { return "option"; },
    NAV: function () { return "navigation"; },
    MAIN: function () { return "main"; },
    FORM: function () { return "form"; }
  };

  function roleOf(el) {
    var explicit = el.getAttribute && el.getAttribute("role");
    if (explicit) return explicit;
    var fn = IMPLICIT_ROLES[el.tagName];
    try {
      return fn ? fn(el) : null;
    } catch (e) {
      return null;
    }
  }

  // ---------------------------------------------------------------------------
  // Kandidat berbasis atribut
  // ---------------------------------------------------------------------------
  function attrCandidate(el, attr) {
    var v = el.getAttribute(attr);
    if (!v || !v.trim() || v.length > 120) return null;
    var css = "[" + attr + '="' + attrValueEscape(v.trim()) + '"]';
    if (attr === "name") css = el.tagName.toLowerCase() + css; // name tidak unik lintas tag
    return { css: css, text: null };
  }

  function roleTextCandidate(el) {
    var role = roleOf(el);
    var text = accessibleText(el);
    if (!role || !text) return null;
    if (el.getAttribute("role")) {
      // Role eksplisit: selector [role=...] valid untuk querySelector.
      var roleSel = '[role="' + role + '"]';
      if (document.querySelector(roleSel)) {
        return { css: roleSel, text: text };
      }
      return null;
    }
    // Role implisit (a[href], button, heading, ...): [role=...] TIDAK cocok
    // di CSS untuk role implisit, jadi pakai tag + teks accessible. Kandidat
    // ini paling tahan terhadap perubahan DOM menu/accordion yang posisi
    // nth-of-type-nya berubah saat menu buka/tutup.
    return { css: el.tagName.toLowerCase(), text: text };
  }

  // ---------------------------------------------------------------------------
  // CSS path pendek + nth-of-type
  // ---------------------------------------------------------------------------
  function levelSelector(el) {
    var tag = el.tagName.toLowerCase();
    var parent = el.parentElement;
    if (!parent) return tag;
    var sameTag = 0, idx = 0;
    for (var i = 0; i < parent.children.length; i++) {
      if (parent.children[i].tagName === el.tagName) {
        sameTag++;
        if (parent.children[i] === el) idx = sameTag;
      }
    }
    if (sameTag > 1 && idx > 0) return tag + ":nth-of-type(" + idx + ")";
    return tag;
  }

  function cssPathCandidates(el) {
    var out = [];
    var node = el;
    var path = "";
    var depth = 0;
    while (node && node.nodeType === 1 && depth <= MAX_ANCESTORS) {
      var seg = levelSelector(node);
      path = path ? seg + " > " + path : seg;

      var candidate = path;
      // Lekatkan ancestor ber-id yang valid sebagai jangkar.
      if (node.id && !looksAutoGenerated(node.id)) {
        candidate = "#" + cssEscape(node.id) + (path !== seg ? " " + path : "");
      }

      var withScope = candidate;
      if (withScope.indexOf("#") === 0 || withScope.indexOf("body") === 0 || withScope.indexOf("html") === 0) {
        out.push(withScope);
      } else {
        out.push("body " + withScope);
      }

      if (node.id && !looksAutoGenerated(node.id)) break; // sudah berjangkar id
      node = node.parentElement;
      depth++;
    }
    return out;
  }

  // ---------------------------------------------------------------------------
  // XPath absolut (kandidat paling akhir)
  // ---------------------------------------------------------------------------
  function absoluteXPath(el) {
    var parts = [];
    var node = el;
    while (node && node.nodeType === 1 && node !== document.documentElement) {
      var idx = 1;
      var sib = node.previousElementSibling;
      while (sib) {
        if (sib.tagName === node.tagName) idx++;
        sib = sib.previousElementSibling;
      }
      parts.unshift(node.tagName.toLowerCase() + "[" + idx + "]");
      node = node.parentElement;
    }
    if (node === document.documentElement) {
      return parts.length ? "/html/" + parts.join("/") : "/html";
    }
    return "/" + parts.join("/");
  }

  // ---------------------------------------------------------------------------
  // Verifikasi keunikan kandidat di dokumen saat record
  // ---------------------------------------------------------------------------
  function countMatches(css, text) {
    try {
      var nodes = document.querySelectorAll(css);
      if (!text) return nodes.length;
      var n = 0;
      for (var i = 0; i < nodes.length; i++) {
        if (selectorGen.elementMatchesText(nodes[i], text)) n++;
      }
      return n;
    } catch (e) {
      return -1; // selector invalid
    }
  }

  // ---------------------------------------------------------------------------
  // Nama manusiawi + sidik jari elemen (fitur "nama step" & verifikasi replay)
  // ---------------------------------------------------------------------------

  /** Teks <label> yang berasosiasi (label[for] / label pembungkus). */
  function labelTextFor(el) {
    var t = "";
    try {
      var labels = el.labels;
      if (labels && labels.length) {
        for (var i = 0; i < labels.length && !t; i++) {
          t = (labels[i].innerText || labels[i].textContent || "").replace(/\s+/g, " ").trim();
        }
      }
    } catch (e) {}
    if (!t && el.closest) {
      var wrap = el.closest("label");
      if (wrap) t = (wrap.innerText || wrap.textContent || "").replace(/\s+/g, " ").trim();
    }
    return t;
  }

  /**
   * Nama manusiawi untuk daftar step (field name / teks tombol), mis.
   * "Username", "Simpan", "Remember me". TIDAK PERNAH membaca nilai password
   * (tidak menyentuh `el.value` kecuali tombol submit/button yang labelnya
   * memang value). Urutan: aria-label → <label> → teks tombol/link →
   * placeholder → alt → title → name attr → id → teks elemen.
   */
  selectorGen.friendlyName = function (el) {
    if (!el || el.nodeType !== 1) return "";
    var tag = el.tagName;
    var t = (el.getAttribute && el.getAttribute("aria-label")) || "";
    if (!t) t = labelTextFor(el);
    if (!t && tag === "INPUT" && /^(submit|button|reset)$/i.test(String(el.type || ""))) {
      t = el.value || "";
    }
    if (!t && (tag === "BUTTON" || tag === "A" || tag === "SUMMARY" || tag === "OPTION")) {
      t = (el.innerText || el.textContent || "").replace(/\s+/g, " ").trim();
    }
    if (!t && el.getAttribute) t = el.getAttribute("placeholder") || "";
    if (!t && el.getAttribute) t = el.getAttribute("alt") || "";
    if (!t && el.getAttribute) t = el.getAttribute("title") || "";
    if (!t && el.getAttribute) {
      var nm = el.getAttribute("name") || "";
      if (nm) t = String(nm).replace(/[_-]+/g, " ").replace(/\s+/g, " ").trim();
    }
    if (!t && el.id && !looksAutoGenerated(el.id)) {
      t = String(el.id).replace(/[_-]+/g, " ").replace(/\s+/g, " ").trim();
    }
    if (!t) t = (el.innerText || el.textContent || "").replace(/\s+/g, " ").trim();
    return String(t).replace(/\s+/g, " ").trim().slice(0, 60);
  };

  /**
   * Sidik jari elemen (tag + tipe input + atribut identitas) — disimpan di
   * step.kind saat merekam, dipakai replayer untuk MENOLAK kandidat yang
   * jenisnya berbeda (akar bug "checkbox hantu" pada form kondisional).
   */
  selectorGen.describeElement = function (el) {
    if (!el || el.nodeType !== 1) return null;
    var tag = el.tagName;
    function attr(name, max) {
      var v = el.getAttribute ? el.getAttribute(name) : null;
      return v ? String(v).slice(0, max || 60) : null;
    }
    return {
      tag: tag,
      inputType: tag === "INPUT" ? String(el.type || "text").toLowerCase() : null,
      role: roleOf(el) || null,
      id: el.id && !looksAutoGenerated(el.id) ? String(el.id).slice(0, 60) : null,
      name: attr("name"),
      ariaLabel: attr("aria-label"),
      placeholder: attr("placeholder")
    };
  };

  // ---------------------------------------------------------------------------
  // API utama
  // ---------------------------------------------------------------------------

  /**
   * Bangun objek selector multi-kandidat untuk elemen.
   * Hasil: { css, text, xpath, alt: [{css, text}...] } — semua data murni.
   */
  selectorGen.buildSelector = function (el) {
    if (!el || el.nodeType !== 1) return null;

    var ordered = []; // [{css, text}] urut prioritas

    // --- 1. atribut test id + id ---
    var testAttrs = ["data-testid", "data-test", "data-cy"];
    for (var i = 0; i < testAttrs.length; i++) {
      var c = attrCandidate(el, testAttrs[i]);
      if (c) ordered.push(c);
    }
    if (el.id && !looksAutoGenerated(el.id)) {
      ordered.push({ css: "#" + cssEscape(el.id), text: null });
    }

    // --- 2. name / aria-label / placeholder / role+text ---
    var attrNames = ["name", "aria-label", "placeholder"];
    for (var j = 0; j < attrNames.length; j++) {
      var c2 = attrCandidate(el, attrNames[j]);
      if (c2) ordered.push(c2);
    }
    var roleC = roleTextCandidate(el);
    if (roleC) ordered.push(roleC);

    // --- 2b. teks tanpa role ---
    // Elemen portal/dropdown modern (react-select, Radix, dsb.) sering <div>
    // polos tanpa role/id/atribut apa pun. Dulu elemen begini hanya dapat
    // jalur CSS — di menu portal jalurnya jadi "body div" yang cocok ratusan
    // node, sehingga saat replay step bisa mengklik <div> lain (customer/
    // status tidak terpilih). Filter teks membuat kandidat ini menunjuk
    // elemen yang benar tanpa bergantung posisi DOM.
    if (!roleC) {
      var txtC = accessibleText(el);
      // Hanya untuk elemen yang teksnya memang "miliknya sendiri" (teks
      // langsung) atau teks totalnya pendek — wadah besar (directText kosong,
      // teks total panjang) bukan target klik yang wajar dan kandidatnya bisa
      // menunjuk leluhur, bukan elemen yang diklik.
      var own = directText(el);
      var full = (el.textContent || "").replace(/\s+/g, " ").trim();
      if (txtC && txtC.length >= 2 && (own || full.length <= 120)) {
        ordered.push({ css: el.tagName.toLowerCase(), text: txtC });
      }
    }

    // --- 3. css path pendek + nth-of-type ---
    var pathCands = cssPathCandidates(el);
    for (var k = 0; k < pathCands.length; k++) {
      ordered.push({ css: pathCands[k], text: null });
    }

    // Dedupe + hitung berapa elemen yang benar-benar cocok dengan tiap kandidat.
    // Kandidat utama = yang pertama unik (1 elemen). Bila TIDAK ADA yang unik
    // sama sekali (DOM portal: seluruh jalurnya luas), pilih yang PALING
    // SPESIFIK (paling sedikit cocok) — dulu jatuh ke kandidat pertama = jalur
    // terluas ("body div", ratusan node) sehingga replay kehilangan petunjuk.
    // Kandidat berfilter teks dihitung 2× lebih spesifik: jalur CSS dengan
    // nth-of-type rapuh terhadap pergeseran DOM, teks tidak.
    var seen = {};
    var list = [];
    for (var m = 0; m < ordered.length; m++) {
      var cand = ordered[m];
      if (seen[cand.css]) continue;
      seen[cand.css] = true;
      var n = countMatches(cand.css, cand.text);
      if (n < 1) continue; // selector invalid atau tidak ada elemen yang cocok
      list.push({ css: cand.css, text: cand.text, n: n, rank: cand.text ? n / 2 : n });
      if (list.length >= MAX_CANDIDATES + 4) break;
    }

    var primary = null;
    var bestRank = Infinity;
    for (var p = 0; p < list.length; p++) {
      if (list[p].n === 1) {
        primary = list[p];
        break;
      }
      if (list[p].rank < bestRank) {
        bestRank = list[p].rank;
        primary = list[p];
      }
    }

    var alts = [];
    for (var q = 0; q < list.length && alts.length < MAX_CANDIDATES; q++) {
      if (list[q] === primary) continue;
      alts.push({ css: list[q].css, text: list[q].text });
    }

    var selector = {
      css: primary ? primary.css : null,
      text: primary ? primary.text : null,
      xpath: absoluteXPath(el),
      alt: alts.map(function (a) {
        return { css: a.css, text: a.text };
      })
    };
    return selector;
  };
})();
